import {painted} from './painted.js';
import {renderer3} from './pass3d.js';
import {volley,phaseTitle,phase} from './patterns.js';
const W=480,H=510,durations=[28,30,37,41];
const clamp=(v,a,b)=>Math.min(b,Math.max(a,v)), seeded=n=>(Math.sin(n*48.2+64.3)*43264%1+1)%1;
const titles=['Điện Biên','Lối gùi hàng','Đường cơ giới','Mùa xuân'];
const btn=(a,t,cl='')=>'<button type="button" class="control '+cl+'" data-a="'+a+'">'+t+'</button>';
const mobileKeys={left:'ArrowLeft',up:'ArrowUp',right:'ArrowRight',down:'ArrowDown'};
function read(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
function write(k,d){try{localStorage.setItem(k,JSON.stringify(d))}catch{}}
export function runRoad(root,stages,cites){
 const dim=document.body.dataset.view==='3d'?'3D':'2D',is3=dim==='3D',key='ky-su-chuyen-hang-v1'+(is3?'-3d':''),mem=read(key,{open:0,won:false,best:0}),prefs=read('ks-arcade-pref',{sound:false,slow:false});
 const limit=clamp(Number(mem.open)||0,0,3);
 let i=limit,mode='intro',renderer=null,can=null,frame=0,generation=0,last=0,time=0,spawn=0,wave=0,inv=0,life=3,px=240,py=398,aim=null,held=new Set,focus=false,focusKey=false,freight=0,near=0,chain=0,peak=0,chainTimer=0,pickAt=3,shots=[],marks=[],effects=[],score=0,tilt=0,lastPhase=0,notice='',noticeTimer=0,dom={},audio=null;
 function tone(type){if(!prefs.sound)return;try{if(!audio){const A=window.AudioContext||window.webkitAudioContext;if(!A)return;audio=new A()}if(audio.state==='suspended')audio.resume().catch(()=>{});const now=audio.currentTime,notes=({get:[660,990],near:[550],hit:[130,82],finish:[440,554,660,880],start:[330,495],phase:[370,465]})[type]||[330];notes.forEach((f,j)=>{const o=audio.createOscillator(),g=audio.createGain(),t=now+.07*j;o.type=type==='hit'?'triangle':'sine';o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(type==='near'?.025:.07,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+.13);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.15)})}catch{}}
 function drop(){generation++;cancelAnimationFrame(frame);frame=0;if(renderer){renderer.dispose();renderer=null}held.clear();aim=null;focusKey=false}
 const badge=()=>'<div class="edition"><a '+(!is3?'aria-current="page"':'')+' href="van-tai.html">2D · Tranh vẽ</a><a '+(is3?'aria-current="page"':'')+' href="van-tai-3d.html">3D · Sa bàn</a></div>';
 function stageTabs(){return '<nav class="stages" aria-label="Chọn chặng">'+titles.map((s,k)=>'<button data-a="stage'+k+'" '+(k>mem.open?'disabled ':'')+(k===i?'aria-current="step"':'')+'><small>0'+(k+1)+'</small>'+s+'</button>').join('')+'</nav>'}
 function state(preview=false){return {i,time,px,py,inv,shots,marks,effects,tilt,focus:focus||focusKey,preview}}
 async function init(canvas,preview){const token=generation;
 try{const r=is3?renderer3(canvas,i):await painted(canvas,i);if(token!==generation){r?.dispose();return false}if(!r)throw Error('renderer');renderer=r;renderer.render(preview?{...state(true),time:1,px:240,py:330,shots:[],marks:[],inv:0,effects:[]}:state());return true}
 catch{if(token===generation){mode='error';root.innerHTML='<div class="briefcard"><small>'+dim+'</small><h2>'+(is3?'Không mở được đồ họa 3D':'Không tải được tranh của chặng')+'</h2><p>'+(is3?'Trình duyệt cần hỗ trợ WebGL. Bạn có thể chơi bản 2D trên cùng thiết bị.':'Kiểm tra mạng rồi thử lại.')+'</p>'+btn('lobby','Thử lại')+' <a href="van-tai.html">Bản 2D →</a></div>'}return false}}
 function intro(){drop();mode='intro';const st=stages[i];root.innerHTML=badge()+'<div class="briefgrid"><figure class="plate"><canvas width="720" height="610" aria-label="Phong cảnh và phương tiện của chặng"></canvas><figcaption>CHẶNG 0'+(i+1)+' &nbsp; / &nbsp; '+st.date+'</figcaption></figure><section class="briefcard"><small>NHẬT TRÌNH &nbsp; / &nbsp; '+st.vehicle+'</small><h2>'+st.title+'</h2><p>'+st.intro+'</p><div class="legend"><span>●</span> Chấm trắng là điểm va chạm. Lướt sát đạn để nối chuỗi; nhặt kiện vàng để ghi điểm.</div>'+btn('go','Xuất phát <span>→</span>','start')+'<div class="settings"><label><input type="checkbox" id="sound" '+(prefs.sound?'checked':'')+'> Âm thanh</label><label><input type="checkbox" id="slow" '+(prefs.slow?'checked':'')+'> Nhịp chậm</label></div></section></div>'+stageTabs()+'<p class="controls-note">Kéo để di chuyển · WASD hoặc phím mũi tên · Giữ Shift hoặc bật Đi chậm để lách qua khe hẹp.</p>'+cites(st.src)+'<small class="caption">Địa danh và niên đại theo tư liệu. Đường chạy, hình ảnh minh họa và các làn đạn được thiết kế cho trò chơi.</small>';can=root.querySelector('canvas');init(can,true)}
 function popup(txt,sec=1.35){notice=txt;noticeTimer=sec;if(dom.wave)dom.wave.textContent=txt}
 function burst(x,y,color,size=23){effects.push({x,y,color,size,age:0,span:.40})}
 function controls(){can.onpointerdown=e=>{if(mode!=='run')return;can.setPointerCapture(e.pointerId);aim={id:e.pointerId,x:e.clientX,y:e.clientY,baseX:px,baseY:py,toX:px,toY:py}};
 can.onpointermove=e=>{if(!aim||aim.id!==e.pointerId)return;const r=can.getBoundingClientRect(),mul=(focus||focusKey)?.70:1.25;const dx=(e.clientX-aim.x)/r.width,dy=(e.clientY-aim.y)/r.height;if(renderer?.dragTarget){[aim.toX,aim.toY]=renderer.dragTarget(aim.baseX,aim.baseY,dx,dy,mul)}else{aim.toX=aim.baseX+dx*W*mul;aim.toY=aim.baseY+dy*H*mul}};
 can.onpointerup=can.onpointercancel=()=>aim=null;
 root.querySelectorAll('[data-dir]').forEach(b=>{const k=mobileKeys[b.dataset.dir];b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);held.add(k)};b.onpointercancel=b.onpointerup=()=>held.delete(k)})}
 async function begin(){drop();mode='loading';time=last=wave=freight=near=chain=peak=chainTimer=score=inv=tilt=lastPhase=0;life=3;px=240;py=398;shots=[];marks=[];effects=[];focus=false;spawn=1.3;pickAt=2.5;const st=stages[i];tone('start');root.innerHTML='<section class="cab"><div class="deck"><div><small>'+dim+' / CHẶNG 0'+(i+1)+' · '+st.date+'</small><b>'+st.title+'</b></div>'+btn('pause','Tạm dừng','pause')+'</div><div class="instruments"><span id="life">♥ ♥ ♥</span><span id="points">0 điểm</span><span id="combo">Chuỗi ×0</span><span id="cargo">0 kiện</span></div><div class="track"><i id="meter"></i></div><div class="playfield"><canvas class="flight" width="720" height="765" tabindex="0" aria-label="Sân chơi '+dim+'"></canvas><div class="paused" hidden><b>Tạm dừng</b>'+btn('pause','Tiếp tục →')+btn('lobby','Về trạm')+'</div></div><div class="flightbar"><b id="wave"></b><span id="distance">0%</span></div><div class="pad">'+Object.entries({left:'←',up:'↑',down:'↓',right:'→'}).map(([k,l])=>'<button data-dir="'+k+'" aria-label="'+({left:'Trái',up:'Lên',down:'Xuống',right:'Phải'}[k])+'">'+l+'</button>').join('')+'<button data-a="focus" aria-pressed="false">Đi chậm</button></div></section>';
 can=root.querySelector('.flight');dom={};for(const k of ['life','points','combo','cargo','wave','distance','meter'])dom[k]=root.querySelector('#'+k);if(!await init(can,false))return;mode='run';can.focus({preventScroll:true});controls();popup(phaseTitle(i,0));frame=requestAnimationFrame(tick)}
 function shot(x,y,dx,dy,r=6,kind=0){shots.push({x,y,dx,dy,r,kind,grazed:false})}
 function tick(now){if(mode!=='run')return;const dt=Math.min(.04,(now-(last||now))/1000)*(prefs.slow?.67:1);last=now;time+=dt;spawn-=dt;pickAt-=dt;noticeTimer-=dt;inv=Math.max(0,inv-dt);chainTimer-=dt;if(chainTimer<=0)chain=0;
 const dur=durations[i],f=time/dur,newPhase=phase(f);if(newPhase!==lastPhase){lastPhase=newPhase;spawn=Math.max(spawn,1);popup('Đợt '+(newPhase+1)+' · '+phaseTitle(i,f),1.8);tone('phase')}
 if(spawn<=0)spawn=volley(i,time,dur,++wave,shot);
 if(pickAt<=0){marks.push({x:60+seeded(Math.floor(time)+i*4)*360,y:-15});pickAt=4.45}
 let vx=0,vy=0,ox=px;const fine=focus||focusKey;if(aim){let speed=fine?310:600;px+=clamp(aim.toX-px,-speed*dt,speed*dt);py+=clamp(aim.toY-py,-speed*dt,speed*dt)}else{if(held.has('ArrowLeft')||held.has('a'))vx--;if(held.has('ArrowRight')||held.has('d'))vx++;if(held.has('ArrowUp')||held.has('w'))vy--;if(held.has('ArrowDown')||held.has('s'))vy++;const l=Math.max(1,Math.hypot(vx,vy)),speed=fine?120:265;px+=vx/l*dt*speed;py+=vy/l*dt*speed}
 px=clamp(px,42,W-42);py=clamp(py,45,H-23);tilt+=(clamp((px-ox)/Math.max(.001,dt*200),-1,1)-tilt)*.20;
 for(const o of shots){o.x+=o.dx*dt;o.y+=o.dy*dt;const d=Math.hypot(o.x-px,o.y-py);if(!inv&&d<o.r+4){life--;inv=1.6;chain=0;chainTimer=0;burst(px,py,'#ffe0a4',34);o.y=H+60;dom.life.textContent='♥ '.repeat(life)+'♡ '.repeat(3-life);popup('Trúng đạn · '+life+' lượt còn lại');tone('hit')}
 else if(!inv&&!o.grazed&&d<o.r+13){o.grazed=true;near++;chain=Math.min(9,chain+1);peak=Math.max(peak,chain);chainTimer=2.1;score+=20*chain;burst(px,py,'#c2ffee',14);popup('Lướt sát  +'+20*chain,.7);tone('near')}}
 shots=shots.filter(o=>o.y<H+23&&o.x>-20&&o.x<W+20);for(const m of marks){m.y+=dt*110;if(Math.hypot(m.x-px,m.y-py)<18){freight++;score+=160;burst(m.x,m.y,'#ffe387',22);m.y=H+60;tone('get');popup('Kiện hàng  +160',.75)}}marks=marks.filter(m=>m.y<H+20);effects.forEach(p=>p.age+=dt);effects=effects.filter(p=>p.age<p.span);
 let pct=Math.min(100,Math.floor(100*f));dom.distance.textContent=pct+'%';dom.meter.style.width=pct+'%';dom.combo.textContent='Chuỗi ×'+chain;dom.cargo.textContent=freight+' kiện';dom.points.textContent=(score+Math.floor(time)*10)+' điểm';dom.wave.textContent=noticeTimer>0?notice:('0'+(lastPhase+1)+' / '+phaseTitle(i,f));
 renderer.render(state());if(life<=0||time>=dur){end(life>0);return}frame=requestAnimationFrame(tick)}
 function pause(){if(mode==='run'){mode='pause';held.clear();aim=null;focusKey=false;cancelAnimationFrame(frame);root.querySelector('.paused').hidden=false;root.querySelector('.pause').textContent='Tiếp tục'}else if(mode==='pause'){mode='run';root.querySelector('.paused').hidden=true;root.querySelector('.pause').textContent='Tạm dừng';last=0;frame=requestAnimationFrame(tick)}}
 function end(win){drop();mode=win?'clear':'over';const st=stages[i],points=score+Math.floor(time)*10+(win?life*100:0);if(win){mem.open=Math.max(mem.open,Math.min(3,i+1));mem.won=mem.won||i===3;mem.best=Math.max(mem.best||0,points);write(key,mem);tone('finish')}
 root.innerHTML=badge()+'<div class="receipt"><small>'+dim+' / '+st.date+' / '+st.vehicle+'</small><h2>'+(win?(i===3?'Đoàn xe về bến':'Hàng đã tới trạm'):'Dừng giữa đường')+'</h2><div class="stats"><b>'+points+'<small>ĐIỂM</small></b><b>'+freight+'<small>KIỆN HÀNG</small></b><b>'+near+'<small>LƯỚT SÁT</small></b><b>×'+peak+'<small>CHUỖI CAO NHẤT</small></b></div><p>'+(win?st.after:'Bạn đã hết lượt chịu va chạm. Các chặng đã mở vẫn được giữ lại.')+'</p>'+cites(st.src)+btn(win?(i===3?'again':'next'):'retry',win?(i===3?'Chơi từ chặng đầu →':'Nhận chuyến tiếp →'):'Thử lại chặng →','start')+btn('lobby','Về trạm')+'</div>';root.focus({preventScroll:true})}
 root.onclick=e=>{const a=e.target.closest('[data-a]')?.dataset.a;if(!a)return;if(a==='go'||a==='retry')begin();else if(a==='pause')pause();else if(a==='focus'&&mode==='run'){focus=!focus;aim=null;root.querySelector('[data-a=focus]').setAttribute('aria-pressed',String(focus))}else if(a==='next'){i++;intro()}else if(a==='again'){i=0;intro()}else if(a==='lobby')intro();else if(a.startsWith('stage')){let k=Number(a.slice(5));if(k>=0&&k<=mem.open){i=k;intro()}}};
 root.addEventListener('change',e=>{if(e.target.id==='slow'||e.target.id==='sound'){prefs[e.target.id]=e.target.checked;write('ks-arcade-pref',prefs);if(e.target.id==='sound')tone('start')}});
 document.addEventListener('keydown',e=>{if(!['run','pause'].includes(mode))return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(Object.values(mobileKeys).includes(k)||['w','a','s','d'].includes(k)){e.preventDefault();held.add(k);aim=null}else if(k==='p'&&!e.repeat)pause();else if(k==='Shift')focusKey=true});
 document.addEventListener('keyup',e=>{held.delete(e.key.length===1?e.key.toLowerCase():e.key);if(e.key==='Shift')focusKey=false});window.addEventListener('blur',()=>{if(mode==='run')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='run')pause()});intro()
}
